"""Self-contained, interactive skeleton preview from checked offline FK samples."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
out=ROOT/'artifacts/right-high-scan-waypoint';d=json.loads((out/'proposal.json').read_text())
visual={k:v for k,v in d.items() if k not in ['positions_rad','times_s','initial_velocity_rad_s']}
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>오른팔 우측 경유점 — 스켈레톤</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#172938;font:15px system-ui,sans-serif}.wrap{max-width:1260px;margin:22px auto;padding:0 22px}h1{font-size:25px;margin:8px 0}.note{color:#536673;line-height:1.6} .tag{display:inline-block;background:#fff1cd;border:1px solid #edcd78;padding:5px 10px;border-radius:7px;font-size:12px} .grid{display:grid;grid-template-columns:1fr 290px;gap:16px;margin:16px 0}.card{background:white;border:1px solid #dce3e9;border-radius:14px;padding:16px;box-shadow:0 3px 15px #24364b09}canvas{display:block;width:100%;height:590px;touch-action:none;border-radius:9px;background:#fbfdff}.controls{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:12px}button,select{border:1px solid #ced8df;border-radius:8px;background:white;padding:8px 12px;cursor:pointer;color:#18374d}button.primary{background:#146b5d;color:white;border:0}input[type=range]{flex:1;min-width:130px;accent-color:#187d69}.value{font:13px ui-monospace,monospace;white-space:nowrap}h2{font-size:16px;margin:0 0 12px}.point{padding:10px;border-left:4px solid;margin:10px 0;background:#f7fafc;line-height:1.7}.small{font-size:12px;color:#687985;line-height:1.6}.stat{padding:9px 0;border-bottom:1px solid #edf0f3;display:flex;justify-content:space-between;gap:8px}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin-top:10px}.dot{width:11px;height:11px;border-radius:50%;display:inline-block;margin-right:5px}.stage{font-size:14px;color:#196c5c;font-weight:650;margin-top:14px}.bottom{padding:13px 0;font-size:12px;line-height:1.8;color:#566b79}@media(max-width:900px){.grid{grid-template-columns:1fr}canvas{height:480px}.wrap{padding:0 12px}}
</style><div class="wrap"><div class="tag">오프라인 제안 · 실행 코드 미적용 · 예시 1개 셀</div><h1>파지 → 우측 경유점 → 스캔자세</h1><div class="note">실제 설치 URDF의 관절 FK 스켈레톤입니다. 드래그로 회전하고 슬라이더로 자세를 확인할 수 있습니다.<br>로봇 우측 = base_link −Y. 주황색은 오른팔, 회색은 기본자세의 왼팔입니다.</div>
<div class="grid"><div class="card"><canvas id="scene"></canvas><div class="legend"><span><i class="dot" style="background:#e4812f"></i>오른팔</span><span><i class="dot" style="background:#929fac"></i>왼팔</span><span><i class="dot" style="background:#159a7a"></i>새 파지점 궤적</span><span><i class="dot" style="background:#bd6871"></i>기존 낮은 상승→스캔</span></div><div class="controls"><button class="primary" id="play">일시정지</button><button id="reset">처음</button><input id="time" type="range" min="0" step="0.01"><span class="value" id="clock"></span><select id="speed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></div><div class="controls"><button onclick="view('front')">정면</button><button onclick="view('right')">우측 사선</button><button onclick="view('top')">위에서</button><label><input id="old" type="checkbox" checked>기존 궤적 비교</label></div><div class="stage" id="stage"></div></div>
<div class="card"><h2>좌표 · base_link · m</h2><div id="points"></div><div class="stat"><span>새 경로 / 접촉 후</span><b id="duration"></b></div><div class="stat"><span>경유점 도달</span><b id="viaTime"></b></div><div class="stat"><span>계획 속도 상한</span><b id="jointScale"></b></div><div class="stat"><span>컨베이어 여유*</span><b id="margin"></b></div><div class="small" style="margin-top:12px">* 팔 캡슐·실측 컨베이어 모델 및 기존 불확실도/여유를 반영한 검사값입니다. 봉투와의 간격은 아닙니다.</div><h2 style="margin-top:22px">현재 오른손 파지점</h2><div class="value" id="xyz"></div><p class="small">접촉 시각 3초는 유지하며, 접촉 직후의 짧은 기존 상승을 이어받아 우측으로 이탈합니다. 스캔보다 약3cm 낮은 경유점을 C2 연속 곡선으로 통과하며 멈추지 않습니다.</p><p class="small">빵 봉투의 크기·최대 높이·기울어짐과 다른 봉투의 시간별 위치는 미측정입니다. 이 미리보기는 움직이는 봉투와의 충돌 회피를 입증하지 않습니다.</p></div></div><div class="bottom">고정 왼팔은 installation.yaml 기본자세입니다. 회색 면은 실제 측정 컨베이어 상면이며 숨은 구조를 재구성한 모델이 아닙니다. 손에 든 봉투의 모양과 부피는 표시하지 않았습니다. 파지 위치·각도가 다른 셀 및 ±90° 전용 궤적은 별도 검사가 필요합니다.</div></div>
<script>const D=__DATA__;window.previewData=D;
const cv=document.querySelector('#scene'),ctx=cv.getContext('2d'),slider=document.querySelector('#time');const total=D.frames.at(-1).t;slider.max=total;
let t=0,playing=true,last=0,az=-.95,el=.42,zoom=1,W=900,H=590,drag=null;
const qp=new URLSearchParams(location.search);if(qp.has('time')){t=Math.min(total,Math.max(0,+qp.get('time')));playing=false;document.querySelector('#play').textContent='재생'}
function fmt(p){return p.map(v=>v.toFixed(3)).join(', ')}
for(const [name,p,color] of [['파지점',D.grasp_xyz_m,'#e4812f'],['새 경유점',D.waypoint_xyz_m,'#169a7a'],['스캔자세',D.scan_xyz_m,'#397bce']])document.querySelector('#points').innerHTML+=`<div class="point" style="border-color:${color}"><b>${name}</b><br><span class="value">${fmt(p)}</span></div>`;
document.querySelector('#jointScale').textContent=Math.round(D.joint_speed_scale*100)+'%';document.querySelector('#duration').textContent=total.toFixed(2)+' s';document.querySelector('#viaTime').textContent=D.waypoint_at_s.toFixed(2)+' s';document.querySelector('#margin').textContent=(D.minimum_conveyor_clearance_m*100).toFixed(1)+' cm';
function view(v){[az,el]=v==='top'?[-Math.PI/2,Math.PI/2]:v==='front'?[0,.10]:[-.95,.42];draw()}window.view=view;
function project(p){let x=p[0]-.24,y=p[1],z=p[2]-.8,s=Math.min(W/1.8,H/1.65)*zoom;return[W/2+(-Math.sin(az)*x+Math.cos(az)*y)*s,H/2-(-Math.cos(az)*Math.sin(el)*x-Math.sin(az)*Math.sin(el)*y+Math.cos(el)*z)*s]}
function line(points,color,width=2,dash=[]){ctx.beginPath();points.forEach((p,i)=>{let q=project(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();ctx.setLineDash([])}
function circle(p,color,r=5){let q=project(p);ctx.beginPath();ctx.arc(...q,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=1.8;ctx.stroke()}
function text(p,str,color,dx=7,dy=-7){let q=project(p);ctx.font='12px system-ui';ctx.fillStyle=color;ctx.fillText(str,q[0]+dx,q[1]+dy)}
function poseAt(time){let i=0;while(i<D.frames.length-2&&D.frames[i+1].t<time)i++;let a=D.frames[i],b=D.frames[Math.min(i+1,D.frames.length-1)],u=Math.max(0,Math.min(1,(time-a.t)/Math.max(.00001,b.t-a.t)));let result={};for(let side of ['left','right'])result[side]=a[side].map((p,j)=>p.map((v,k)=>v+(b[side][j][k]-v)*u));return result}
function draw(){ctx.clearRect(0,0,W,H);for(let x=-.2;x<=1.;x+=.2)line([[x,-.7,0],[x,.7,0]],'#edf1f4',1);for(let y=-.6;y<=.6;y+=.2)line([[-.2,y,0],[1,y,0]],'#edf1f4',1);
for(let poly of D.conveyor_polygons){ctx.beginPath();poly.forEach((p,i)=>{let q=project(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle='#7d969722';ctx.fill();ctx.strokeStyle='#78919166';ctx.lineWidth=1;ctx.stroke()}
if(document.querySelector('#old').checked)line(D.old_ee_path_m,'#bd687188',2,[6,5]);line(D.ee_path_m,'#159a7a99',3);
for(let [p,color,label] of [[D.grasp_xyz_m,'#e4812f','파지'],[D.waypoint_xyz_m,'#159a7a','우측 경유점'],[D.scan_xyz_m,'#397bce','스캔']]){circle(p,color,6);text(p,label,color)}
let f=poseAt(t),a=f.left[0],b=f.right[0],mid=a.map((v,i)=>(v+b[i])/2);line([[0,0,0],[0,0,mid[2]],mid],'#9ba9b6',7);line([a,b],'#9ba9b6',6);
for(let [side,color] of [['left','#98a4b0'],['right','#e4812f']]){line(f[side],color,6);f[side].forEach(p=>circle(p,color,4))}circle(f.right.at(-1),'#d75025',7);
const origin=[-.14,-.36,.04];for(let [delta,label,color]of [[[.16,0,0],'+X','#d25454'],[[0,.16,0],'+Y','#458754'],[[0,0,.16],'+Z','#4077bc']]){let e=origin.map((v,i)=>v+delta[i]);line([origin,e],color,2);text(e,label,color)}
text([.38,-.62,.92],'로봇 우측 (−Y)','#456573');text([.61,.47,.83],'물체 이동 −Y · 0.09m/s','#657b86');line([[.61,.45,.84],[.61,.25,.84]],'#899eab',2);
slider.value=t;document.querySelector('#clock').textContent=t.toFixed(2)+' / '+total.toFixed(2)+' s';document.querySelector('#xyz').textContent=fmt(f.right.at(-1));document.querySelector('#stage').textContent=t>=total-.02?'스캔자세 도착':t<D.original_lift_prefix_s?'파지 직후: 기존 추종·상승 연결':t<D.waypoint_at_s?'우측으로 이탈 → 경유점':'경유점 → 스캔자세 (멈춤 없이 연결)';}
function resize(){let box=cv.getBoundingClientRect();W=box.width;H=box.height;let dpr=devicePixelRatio||1;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}addEventListener('resize',resize);
document.querySelector('#play').onclick=()=>{if(t>=total)t=0;playing=!playing;document.querySelector('#play').textContent=playing?'일시정지':'재생'};document.querySelector('#reset').onclick=()=>{t=0;draw()};slider.oninput=()=>{t=+slider.value;playing=false;document.querySelector('#play').textContent='재생';draw()};document.querySelector('#old').onchange=draw;
cv.onpointerdown=e=>{drag=[e.clientX,e.clientY,az,el];cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(!drag)return;az=drag[2]-(e.clientX-drag[0])*.008;el=Math.max(.03,Math.min(Math.PI/2,drag[3]+(e.clientY-drag[1])*.006));draw()};cv.onpointerup=()=>drag=null;cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.6,Math.min(2.3,zoom*Math.exp(-e.deltaY*.001)));draw()};
window.seekTo=s=>{t=Math.min(total,Math.max(0,s));playing=false;draw()};function tick(now){if(playing&&last){t+=Math.min(.1,(now-last)/1000)*+document.querySelector('#speed').value;if(t>=total){t=total;playing=false;document.querySelector('#play').textContent='재생'}}last=now;draw();requestAnimationFrame(tick)}resize();requestAnimationFrame(tick);
</script></html>'''
(out/'preview.html').write_text(html.replace('__DATA__',json.dumps(visual,separators=(',',':'))))
print((out/'preview.html').as_uri())
